/* =====================================================================
 *  snpcurate.js — SNPCurate: a registry of published maize alleles and what
 *  this release shows of each.
 *
 *  Data: window.SNP_CURATE (js/snpcurate.data.js), generated by
 *  tools/build_snpcurate.py from data/curate/snpcurate.source.json, the variant
 *  stores and their site-QC sidecars, the catalogue and the GRIN trait file.
 *  A table of the entries with filters, and a record view below it; a record
 *  opens from another tool with openCurate(id) (S.curateId). Marks (curateBadge
 *  in data.js): gold, a published causal change that is a site in this release;
 *  silver, a published variant, marker or lead SNP that is a site; white, a
 *  published variant that is not in this marker set.
 * ===================================================================== */
(function () {

  const CU = { fText:'', fMark:'all', fStatus:'all', sortKey:null, sortDir:1, busy:null,
               lines:[], linesReport:null };     // the lines panel: accession ids in the order given, and the last load's report
  const STATUS = {
    site:          {label:'Site in this release'},
    not_a_site:    {label:'Not a site',         why:'The release has no site at this position, so it cannot show the allele.'},
    different_allele:{label:'Site, different allele', why:'The release has a site at this position, but with a different allele from the published one.'},
    not_locatable: {label:'Not locatable',      why:'The change cannot be placed on the B73 v5 gene model the release is annotated with.'},
    structural:    {label:'Structural variant', why:'The allele is a transposon or indel haplotype, which a release of SNPs and short indels cannot genotype.'},
    unreliable:    {label:'Calls unreliable',   why:'Most sites in this gene are dominated by heterozygous calls, so the release cannot genotype the allele series reliably.'},
    not_annotated: {label:'Gene not annotated', why:'The gene model is missing from the annotation behind the release’s consequence calls.'},
  };
  const MARKS = ['gold','silver','white'];
  const MARK_NAME = {gold:'Gold', silver:'Silver', white:'White'};
  const MARK_ORDER = {gold:0, silver:1, white:2};
  // PlantCAD2: the one-pass score (release v1.4.3, 8,192-bp windows), as in the other tools; the data file keeps
  // the 512-bp pc2 too
  const SCORE_LABEL = [['pc1','PlantCAD1'],['pc2op','PlantCAD2'],['evo2','Evo2'],['esm1','ESM1'],['esm2','ESM2'],['esm3','ESM3'],['esmc','ESM-C']];
  /* what the publication says the variant is (the source's role field) */
  const ROLE = {causal:'Causal change', proposed:'Proposed causal change', allele:'Allele-defining change', associated:'Associated variant',
                lead_snp:'Lead SNP', marker:'Published marker'};
  /* the favorable allele as the publication reads it (the source's favorable field) */
  const FAV = {alt:'Alternate', ref:'Reference', depends:'Depends', unknown:'—'};
  const FAV_TIP = {alt:'The alternate allele is the one a breeder wants.', ref:'The reference allele (B73\u2019s) is the one a breeder wants.',
                   depends:'Which allele is wanted depends on the goal, market class or latitude.', unknown:'The publication gives no direction, or the alleles are not given.'};
  const GT_WORD = {ref:'Ref', het:'Het', alt:'Alt', missing:'Missing'};
  const GT_LONG = {ref:'homozygous for the reference allele', het:'heterozygous', alt:'homozygous for the alternate allele', missing:'a missing call'};

  function esc(s){ return String(s==null?'':s).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;'); }
  function data(){ return (typeof window!=='undefined' && window.SNP_CURATE) || null; }
  function entries(){ return (data() && data().entries) || []; }
  function byId(id){ return entries().find(e=>e.id===id) || null; }
  function carriers(e){ return e.site ? e.site.nHet + e.site.nHom : null; }
  /* The records are read from the Imputed set; a set with a site rule (High Quality) holds the same
     record, unchanged, or not at all. '' when the site is in the chosen set. */
  function notInSet(e){ return e.site ? Data.notInSetReason(ds(), e.site.nHet, e.site.nHom, e.site.maxr2) : ''; }
  function fmt(v){ return v==null ? '—' : (Math.abs(v)>=100 ? Math.round(v).toLocaleString() : (+v).toFixed(2)); }
  function sc1(v){ return v==null ? '—' : (v>0?'+':'') + (+v).toFixed(1); }
  function pct(a,b){ return b ? ` (${Math.round(100*a/b)}%)` : ''; }
  function where(e){
    const c=(e.chr||'').replace('chr','chr');
    if (e.pos) return `${c}:${(+e.pos).toLocaleString()}`;
    if (e.codon_positions && e.codon_positions.length) return `${c}:${(+e.codon_positions[0]).toLocaleString()}-${(+e.codon_positions[e.codon_positions.length-1]).toLocaleString()} (codon)`;
    if (e.start) return `${c}:${(+e.start).toLocaleString()}-${(+e.end).toLocaleString()}`;
    return c;
  }
  function change(e){ return e.site && e.site.sub ? `${e.label}` : e.label; }
  function favHTML(e){ const f=e.favorable||'unknown'; const tip=(e.favorable_note? esc(e.favorable_note)+' ' : '')+esc(FAV_TIP[f]||'');
    return `<span class="cur-fav cur-fav-${esc(f)}" data-tt="${tip}">${FAV[f]||'—'}</span>`; }
  function b73HTML(e){ const s=e.site; if (!s || !s.b73) return '<span class="muted">—</span>';
    return `<span class="cur-b73 cur-b73-${esc(s.b73)}" data-tt="B73 is ${esc(GT_LONG[s.b73]||s.b73)} at this site.">${esc(GT_WORD[s.b73]||s.b73)}</span>`; }
  /* "Zheng et al. 2008" from a citation "Zheng P, et al. 2008. Nat Genet 40:367-372" */
  function shortCite(cite){
    const m=/^(.*?)\s(\d{4})\./.exec(cite||''); if (!m) return String(cite||'').replace(/\.\s.*$/,'');
    const names=m[1].split(/,\s*/).map(x=>x.trim()).filter(Boolean), first=(names[0]||'').split(' ')[0];
    if (names.length>2 || names.some(x=>/^et al/.test(x))) return `${first} et al. ${m[2]}`;
    if (names.length===2) return `${first} & ${names[1].split(' ')[0]} ${m[2]}`;
    return `${first} ${m[2]}`;
  }
  function compositePct(z){ return Data.compositePercentile ? Data.compositePercentile(z, ds()) : null; }
  function ordinal(n){ const s=['th','st','nd','rd'], v=n%100; return n+(s[(v-20)%10]||s[v]||s[0]); }
  function prioPill(p){ return p ? `<span class="prio ${p.toLowerCase()}">${p}</span>` : '<span class="muted">—</span>'; }

  /* ---------- filters + sort ---------- */
  function visible(){
    const q = CU.fText.trim().toLowerCase();
    let L = entries().filter(e =>
      (!q || (e.trait+' '+e.symbol+' '+e.gene).toLowerCase().includes(q)) &&
      (CU.fMark==='all' || e.mark===CU.fMark) &&
      (CU.fStatus==='all' || e.status===CU.fStatus));
    // default order: by mark (gold, silver, white), then gene name; a header click sorts by gene or carriers
    if (!CU.sortKey) L = L.slice().sort((a,b)=>(MARK_ORDER[a.mark]-MARK_ORDER[b.mark]) || String(a.symbol).localeCompare(String(b.symbol)) || a.id.localeCompare(b.id));
    if (CU.sortKey==='gene') L = L.slice().sort((a,b)=>CU.sortDir*String(a.symbol).localeCompare(String(b.symbol)) || a.id.localeCompare(b.id));
    if (CU.sortKey==='carriers') L = L.slice().sort((a,b)=>{ const x=carriers(a), y=carriers(b);
      if (x==null && y==null) return a.id.localeCompare(b.id); if (x==null) return 1; if (y==null) return -1; return CU.sortDir*(x-y); });
    return L;
  }

  /* ---------- page ---------- */
  function render(page){
    page = page || document.getElementById('page');
    injectCSS();
    // a permalink's lines (#snpcurate?lines=<ids>, core.js applyRoute sets S.curateLines)
    if (S.curateLines){ const ids=S.curateLines.filter(id=>Data.accessionById && Data.accessionById(id)); S.curateLines=null; CU.lines=ids; CU.linesReport={matched:ids.length, unmatched:[], fanout:0, considered:ids.length}; }
    page.className = 'page fade';
    const D = data();
    if (!D){
      page.innerHTML = head() + `<div class="empty-state"><div class="ei">${ICONS.check||''}</div><h3>No curated alleles loaded</h3>
        <p>SNPCurate reads <span class="c-mono">js/snpcurate.data.js</span>, built by <span class="c-mono">make curate</span>.</p></div>`;
      return;
    }
    const counts = {gold:0, silver:0, white:0}; entries().forEach(e=>{ counts[e.mark]=(counts[e.mark]||0)+1; });
    const stat = Object.keys(STATUS).filter(k=>entries().some(e=>e.status===k));
    page.innerHTML = head() + `
      <div class="card pad cur-legend" id="curLegend">
        ${MARKS.map(m=>`<div class="cur-lg">${curateBadge({id:'', mark:m, symbol:'', label:''}).replace(/onclick="[^"]*"/,'onclick="return false;"').replace(/ data-curate="[^"]*"/,'')}
          <span><b>${MARK_NAME[m]}</b> · ${esc(D.marks[m])} <span class="muted">(${counts[m]||0})</span></span></div>`).join('')}
      </div>
      <div class="filterbar cur-filters">
        <div class="fld"><label for="curText">Trait or gene</label>
          <input id="curText" type="search" value="${esc(CU.fText)}" placeholder="e.g. kernel color, su1" oninput="CURATE.setFilter('fText', this.value)"></div>
        <div class="fld"><label for="curMark">Mark</label>
          <select id="curMark" onchange="CURATE.setFilter('fMark', this.value)">
            <option value="all">All marks</option>${MARKS.map(m=>`<option value="${m}" ${CU.fMark===m?'selected':''}>${MARK_NAME[m]}</option>`).join('')}</select></div>
        ${Data.datasets().length>1?`<div class="fld"><label for="curDataset" data-tt="The set the hand-offs query. The records are read from the Imputed set; the High Quality set holds the same record at each site it keeps.">Dataset</label>
          <select id="curDataset" onchange="CURATE.setDataset(this.value)">${Data.datasets().map(d=>`<option value="${esc(d.id)}" ${d.id===ds()?'selected':''}>${esc(Data.datasetLabel(d.id))}</option>`).join('')}</select></div>`:''}
        <div class="fld"><label for="curStatus">Status in this release</label>
          <select id="curStatus" onchange="CURATE.setFilter('fStatus', this.value)">
            <option value="all">Any status</option>${stat.map(k=>`<option value="${k}" ${CU.fStatus===k?'selected':''}>${esc(STATUS[k].label)}</option>`).join('')}</select></div>
      </div>
      <div id="curLines">${linesPanelHTML()}</div>
      <div id="curTable">${tableHTML()}</div>
      <div id="curRecord">${S.curateId ? recordHTML(byId(S.curateId)) : ''}</div>`;
    if (typeof attachTT==='function') attachTT();
    if (S.curateId){ const r=document.getElementById('curRecord'); if (r && r.scrollIntoView) r.scrollIntoView({block:'start'}); }
    writeRoute();
  }
  /* the permalink: #snpcurate/SC0003, with ?lines=<ids> when the lines panel holds lines */
  function writeRoute(){
    const rec = S.curateId ? byId(S.curateId) : null;
    if (typeof setRoute==='function') setRoute('snpcurate', rec ? rec.id : '', rec ? `${rec.symbol} ${rec.label}` : (CU.lines.length ? `${CU.lines.length} lines` : ''),
      CU.lines.length ? 'lines=' + CU.lines.map(encodeURIComponent).join(',') : '');
  }

  /* ---------- the lines panel: which published alleles do these lines carry ----------
     Rows are the lines (pasted, the SNPVersity selection, or the NAM founders), columns the site
     entries in the table's order; a cell is the line's genotype at the site, read from the data
     file's carrier lists (hom, het, missing: everything else is the reference call). A line with a
     missing call at a site shows "?". The favorable allele colours the cell: green when the line is
     homozygous for it, pale green when heterozygous. Nothing is queried. */
  function siteEntries(){
    return entries().filter(e=>e.site).slice().sort((a,b)=>(MARK_ORDER[a.mark]-MARK_ORDER[b.mark]) || String(a.symbol).localeCompare(String(b.symbol)) || a.id.localeCompare(b.id));
  }
  function gtAt(e, id){ const c=e.site.carriers; return c.hom.indexOf(id)>=0 ? 'alt' : c.het.indexOf(id)>=0 ? 'het' : (c.missing||[]).indexOf(id)>=0 ? 'missing' : 'ref'; }
  const GT_GLYPH = {alt:'H', het:'h', ref:'\u00b7', missing:'?'};
  /* carries the favorable allele: 'hom', 'het' or '' (also '' when the favorable allele is not known) */
  function favCarry(e, gt){
    const f=e.favorable;
    if (f==='alt') return gt==='alt' ? 'hom' : gt==='het' ? 'het' : '';
    if (f==='ref') return gt==='ref' ? 'hom' : gt==='het' ? 'het' : '';
    return '';
  }
  function lineLabel(id){ const a=Data.accessionById ? Data.accessionById(id) : null; return a ? (a.label || a.strain || id) : id; }
  function lineSub(id){ const a=Data.accessionById ? Data.accessionById(id) : null; return a ? (a.subpop || '') : ''; }
  function linesPanelHTML(){
    const n=(S.selected&&S.selected.size)||0, E=siteEntries();
    const rep=CU.linesReport;
    const status = rep ? `<div class="cur-sub" id="curLinesStatus">${rep.matched} line${rep.matched===1?'':'s'} loaded${rep.fanout?` (${rep.fanout} entries matched several lines)`:''}${rep.unmatched.length?` · <span class="cur-out">${rep.unmatched.length} not found: ${esc(rep.unmatched.slice(0,5).join(', '))}${rep.unmatched.length>5?'…':''}</span>`:''}</div>` : '';
    return `<div class="card pad cur-lines">
      <div class="cur-lines-h"><div><div class="n" style="margin:0">YOUR LINES</div><h3 style="margin:2px 0 4px">Which published alleles do these lines carry?</h3>
        <p class="cur-sub" style="margin:0">Paste accession ids, line names or GRIN numbers (one per line), or take the SNPVersity selection. Each line's genotype at the ${E.length} genotyped alleles is read from the registry; nothing is queried. Click a column to select its carriers for SNPVersity.</p></div></div>
      <div class="cur-lines-ctl">
        <textarea id="curLinesPaste" rows="3" placeholder="B73\nIl14H\nPI 550473" spellcheck="false" aria-label="Lines to look up, one per line"></textarea>
        <div class="cur-lines-btns">
          <button class="btn" onclick="CURATE.loadLines(document.getElementById('curLinesPaste').value)">${ICONS.search||''} Load lines</button>
          <button class="btn ghost" onclick="CURATE.useSelection()" ${n?'':'disabled'}>Use the SNPVersity selection (${n.toLocaleString()})</button>
          <button class="btn ghost" onclick="CURATE.useFounders()">NAM founders</button>
          ${CU.lines.length?`<button class="btn ghost" onclick="CURATE.clearLines()">Clear</button>`:''}
        </div>
      </div>
      ${status}
      ${CU.lines.length ? linesMatrixHTML(E) : ''}
    </div>`;
  }
  function linesMatrixHTML(E){
    const favN = E.filter(e=>e.favorable==='alt'||e.favorable==='ref').length;
    const head = E.map(e=>`<th class="cur-lcol" data-id="${esc(e.id)}" onclick="CURATE.selectCarriers('${esc(e.id)}')" data-tt="${esc(e.symbol)} ${esc(e.label)} · ${esc(e.trait)} · favorable: ${esc(FAV[e.favorable||'unknown'])}${e.favorable_note?' ('+esc(e.favorable_note)+')':''}. Click to select its ${(e.site.nHet+e.site.nHom).toLocaleString()} carriers for SNPVersity."><span class="cur-lsym">${curateBadge(e)} ${esc(e.symbol)}</span><span class="cur-llab">${esc(e.label.replace(/\s*\(.*$/,''))}</span></th>`).join('');
    const rows = CU.lines.map(id=>{
      let fav=0, alt=0;
      const cells = E.map(e=>{ const gt=gtAt(e,id), c=favCarry(e,gt); if (c==='hom') fav++; if (gt==='alt') alt++;
        return `<td class="cur-lc cur-lc-${gt}${c?' cur-lc-fav'+c:''}" data-tt="${esc(lineLabel(id))} · ${esc(e.symbol)} ${esc(e.label)}: ${esc(GT_LONG[gt]||gt)}${c?' (the favorable allele)':''}">${GT_GLYPH[gt]}</td>`; }).join('');
      return `<tr><th class="cur-lrow"><b>${esc(lineLabel(id))}</b><div class="cur-sub">${esc(id)}${lineSub(id)?' · '+esc(lineSub(id)):''}</div></th>${cells}<td class="num" data-tt="Homozygous for the favorable allele at how many of the ${favN} alleles whose favorable allele is known.">${fav} <span class="muted">of ${favN}</span></td><td class="num" data-tt="Homozygous for the alternate allele at how many of the ${E.length} genotyped alleles.">${alt}</td></tr>`;
    }).join('');
    return `<div class="cur-lines-acts">
        <span class="cur-sub"><b>${CU.lines.length.toLocaleString()}</b> line${CU.lines.length===1?'':'s'} × ${E.length} genotyped alleles · H homozygous alternate · h heterozygous · · reference · ? missing ·
          <span class="cur-lc cur-lc-favhom cur-key">H</span> the favorable allele <span class="cur-lc cur-lc-favhet cur-key">h</span> heterozygous for it ·
          <span class="cur-lc cur-lc-alt cur-key">H</span> alternate where the favorable allele is the reference, depends on the goal, or is not known</span>
        <button class="btn ghost" onclick="CURATE.linesDownload()">${ICONS.download||''} TSV</button>
        <button class="btn ghost" onclick="CURATE.linesToSelection()" data-tt="Make these lines the SNPVersity selection.">Set as the selection</button>
      </div>
      <div class="tbl-wrap cur-lines-wrap"><table class="cur-lines-tbl" id="curLinesTbl"><thead><tr><th class="cur-lrow">Line</th>${head}<th class="num">Favorable</th><th class="num">Alt</th></tr></thead><tbody>${rows}</tbody></table></div>`;
  }
  /* rows of the TSV: one per line, a column per genotyped allele (alt / het / ref / missing) */
  function linesTSV(){
    const E=siteEntries();
    const head=['accession','line','subpopulation'].concat(E.map(e=>`${e.id} ${e.symbol} ${e.label}`)).concat(['favorable_hom','alt_hom']);
    const out=[head.join('\t')];
    CU.lines.forEach(id=>{ let fav=0, alt=0; const g=E.map(e=>{ const gt=gtAt(e,id); if (favCarry(e,gt)==='hom') fav++; if (gt==='alt') alt++; return gt; });
      out.push([id, lineLabel(id), lineSub(id)].concat(g).concat([fav, alt]).join('\t')); });
    return out.join('\n')+'\n';
  }
  /* resolve pasted ids, names and GRIN numbers with SNPVersity's resolver (snpversity.js) */
  function resolveLines(text){
    const idx = (typeof buildAccIndex==='function') ? buildAccIndex() : null;
    const seen=new Set(), ids=[], unmatched=[]; let fanout=0, considered=0;
    String(text||'').split(/\r\n|\r|\n/).forEach(raw=>{
      const line=String(raw).trim(); if (!line || /^[#!]/.test(line)) return;
      considered++;
      let hit = idx && typeof resolveAccEntry==='function' ? resolveAccEntry(line, idx) : null;
      if (!hit || !hit.ok){ const a=Data.accessionById ? Data.accessionById(line) : null; hit = a ? {ok:true, ids:[a.id]} : null; }
      if (!hit || !hit.ok){ unmatched.push(line); return; }
      if (hit.ids.length>1) fanout++;
      hit.ids.forEach(id=>{ if (!seen.has(id)){ seen.add(id); ids.push(id); } });
    });
    return {ids, unmatched, fanout, considered, matched: ids.length};
  }
  function setLines(ids, report){
    CU.lines = ids.slice(); CU.linesReport = report || {matched: ids.length, unmatched:[], fanout:0, considered: ids.length};
    const host=document.getElementById('curLines'); if (host){ host.innerHTML=linesPanelHTML(); if (typeof attachTT==='function') attachTT(); }
    writeRoute();
  }
  function head(){
    return `<div class="sec"><div class="bar"></div><div>
      <div class="n">PUBLISHED ALLELES · ${esc((data()||{}).release||'')}</div>
      <h2>Curated alleles and what this release shows of them</h2>
      <p>Variants published for maize genes, each with its carriers, Site QC class, scores and trait means in
      this release. Only variants a publication names are listed; a published variant that is not in this
      marker set is listed with the reason. Click a row for its record.</p>
    </div></div>`;
  }
  function th(label, key, tt){
    if (!key) return `<th data-tt="${esc(tt)}">${label}</th>`;
    const on = CU.sortKey===key, arrow = on ? (CU.sortDir>0?' ▲':' ▼') : ' ⇅';
    return `<th class="sortable ${on?'on':''}" data-tt="${esc(tt)}" onclick="CURATE.sort('${key}')">${label}<span class="arr">${arrow}</span></th>`;
  }
  function tableHTML(){
    const L = visible();
    if (!L.length) return `<div class="card pad muted">No curated allele matches these filters.</div>`;
    const rows = L.map(e=>{ const s=e.site, open=S.curateId===e.id;
      return `<tr class="imp-row ${open?'open':''}" data-id="${esc(e.id)}" onclick="CURATE.open('${esc(e.id)}')">
        <td style="padding-left:11px">${curateBadge(e)}</td>
        <td><b>${esc(e.symbol)}</b><div class="c-mono cur-sub">${esc(e.gene)}</div></td>
        <td>${esc(change(e))}</td>
        <td>${esc(e.trait)}</td>
        <td>${favHTML(e)}</td>
        <td>${esc(STATUS[e.status] ? STATUS[e.status].label : e.status)}${notInSet(e)?`<div class="cur-sub cur-out" data-tt="${esc(notInSet(e))}">not in the ${esc(setShort())} set</div>`:''}</td>
        <td class="num">${s ? `${s.nHet.toLocaleString()} / <b>${s.nHom.toLocaleString()}</b>` : '<span class="muted">—</span>'}</td>
        <td>${b73HTML(e)}</td>
        <td>${s ? siteQcPill(s.qc, s.nHet, s.nHom) : ''}</td>
        <td>${s ? prioPill(s.priority) : '<span class="muted">—</span>'}</td>
        <td class="cur-ref">${e.refs && e.refs[0] ? esc(shortCite(e.refs[0].cite)) + (e.refs.length>1?` <span class="muted">+${e.refs.length-1}</span>`:'') : ''}</td>
      </tr>`; }).join('');
    return `<div class="tbl-wrap" style="max-height:none"><table class="vcf imp cur-table">
      <thead><tr>${th('Mark','', 'Gold: published causal change, a site in this release. Silver: published variant, marker or lead SNP, a site here; causality not established. White: published variant that is not in this marker set.')}
        ${th('Gene','gene','Gene symbol and B73 v5 model. Click to sort.')}${th('Change','','The published change.')}${th('Trait','','The trait the allele affects.')}
        ${th('Favorable allele','','Which allele a breeder wants, as the publication reads it: the alternate, the reference (B73\u2019s), or it depends (hover for what on).')}
        ${th('Status in this release','','Whether the release genotypes the allele, and why not when it does not.')}
        ${th('Carriers (het / hom)','carriers','Heterozygous / homozygous carriers among the release lines. Click to sort.')}
        ${th('B73','','B73\u2019s genotype at the site: Ref, Het or Alt.')}
        ${th('Site QC','','The class of the site from its heterozygous and homozygous carriers.')}${th('Priority','','The SNPMaize priority of the change, as SNPImpact computes it.')}${th('Reference','','The first publication; the record lists all.')}</tr></thead>
      <tbody>${rows}</tbody></table></div>
      <div class="pager"><div class="info">Showing <span class="mono">${L.length}</span> of <span class="mono">${entries().length}</span> published alleles · <span class="mono">${new Set(L.map(e=>e.gene)).size}</span> of <span class="mono">${new Set(entries().map(e=>e.gene)).size}</span> genes</div></div>`;
  }

  /* ---------- record ---------- */
  function recordHTML(e){
    if (!e) return '';
    const s = e.site;
    const refs = (e.refs||[]).map(r=>`<li>${esc(r.cite)}${r.doi?` · <a href="https://doi.org/${esc(r.doi)}" target="_blank" rel="noopener">doi:${esc(r.doi)}</a>`:''}</li>`).join('');
    const review = e.needs_review ? `<div class="cur-review" role="note"><b>To confirm:</b> ${esc(e.needs_review)}</div>` : '';
    const pub = e.published_as ? `<p class="cur-pub"><span class="cur-k" style="display:inline">Published as</span> ${esc(e.published_as)}</p>` : '';
    const top = `<div class="cur-rh">
        <div>${curateBadge(e)} <b class="cur-sym">${esc(e.symbol)}</b> <span class="cur-lbl">${esc(e.label)}</span>
          <div class="muted cur-sub">${esc(e.id)} · <a class="c-mono" href="${maizegdbGeneURL(e.gene)}" target="_blank" rel="noopener">${esc(e.gene)}</a>
          · ${esc(ROLE[e.role]||e.role)} · ${esc(e.trait)}</div></div>
        <button class="btn ghost" onclick="CURATE.close()" aria-label="Close the record">✕</button></div>`;
    if (!s){
      const st = STATUS[e.status] || {label:e.status, why:''};
      return `<div class="card pad cur-record" id="curRec_${esc(e.id)}">${top}
        <div class="cur-why"><b>${esc(st.label)}.</b> ${esc(st.why)} <span class="muted">(${esc(where(e))})</span></div>
        ${e.favorable&&e.favorable!=='unknown'?`<p class="cur-pub"><span class="cur-k" style="display:inline">Favorable allele</span> ${favHTML(e)}${e.favorable_note?` <span class="muted">· ${esc(e.favorable_note)}</span>`:''}</p>`:''}
        <p>${esc(e.note||'')}</p>${pub}${review}
        <div class="cur-k" style="margin-top:12px">References</div><ul class="cur-refs">${refs}</ul></div>`;
    }
    const gene = s.gene!==e.gene ? ` in <span class="c-mono" style="text-transform:none">${esc(s.gene)}</span>` : '';
    const scores = SCORE_LABEL.map(([k,l])=>`<div class="cur-score"><span>${l}</span><b class="mono">${sc1(s.scores[k])}</b>${s.rank&&s.rank[k]?`<span class="muted">rank ${s.rank[k][0]} of ${s.rank[k][1]}</span>`:''}</div>`).join('');
    const subs = s.subpop.filter(x=>x.hom).map(x=>`<tr><td>${esc(x.name)}</td><td class="num">${x.hom.toLocaleString()} of ${x.total.toLocaleString()}${pct(x.hom,x.total)}</td></tr>`).join('');
    const ctys = s.country.map((x,i)=>`<tr${i>=12?' class="cur-more" hidden':''}><td>${esc(x.name)}</td><td class="num">${x.carriers.toLocaleString()} of ${x.total.toLocaleString()}${pct(x.carriers,x.total)}</td></tr>`).join('');
    return `<div class="card pad cur-record" id="curRec_${esc(e.id)}">${top}
      ${notInSet(e)?`<div class="cur-why" id="curOut"><b>Not in the ${esc(setShort())} set.</b> ${esc(notInSet(e))}. The record below is the Imputed set's; SNPVersity and SNPFunction show the gene without this site.</div>`:''}
      <div class="cur-actions">
        <button class="btn" onclick="CURATE.toVersity('${esc(e.id)}')" ${carriers(e)?'':'disabled'}>${ICONS.dna||''} Carriers in SNPVersity</button>
        <button class="btn" onclick="CURATE.toFunction('${esc(e.id)}')">${ICONS.func||''} Gene in SNPFunction</button>
        <button class="btn" onclick="CURATE.toMap('${esc(e.id)}')" ${notInSet(e)?`disabled title="The ${esc(setShort())} set has no record at this site."`:''}>${ICONS.map||''} Send to SNPGeo</button>
        <span class="muted" id="curBusy">${CU.busy===e.id?'Querying all lines…':''}</span>
      </div>
      <div class="cur-grid cur-facts">
        <div><div class="cur-k">Site</div><div class="cur-v mono">${esc(e.chr)}:${(+e.pos).toLocaleString()} ${esc(e.ref.length>12?e.ref.slice(0,12)+'…':e.ref)}&gt;${esc(e.alt.length>12?e.alt.slice(0,12)+'…':e.alt)}</div></div>
        <div><div class="cur-k">Consequence${gene}</div><div class="cur-v"><span class="cons ${esc(s.consClass)}">${esc(s.consequence)}</span>${s.sub?` <span class="c-mono">${esc(s.sub)}</span>`:''} <span class="muted">${esc(s.impact)}</span></div></div>
        <div><div class="cur-k">Site QC</div><div class="cur-v">${siteQcPill(s.qc, s.nHet, s.nHom)} ${s.nHet.toLocaleString()} het · ${s.nHom.toLocaleString()} hom · ${s.nMiss.toLocaleString()} missing</div></div>
        <div><div class="cur-k">Allele frequency</div><div class="cur-v">${s.af==null?'—':(s.af*100).toFixed(1)+'%'} <span class="muted">among called lines · MAF ${s.maf==null?'—':s.maf} · max LD r² ${s.maxr2==null?'—':s.maxr2}</span></div></div>
        <div><div class="cur-k">Favorable allele</div><div class="cur-v">${favHTML(e)}${e.favorable_note?` <span class="muted">· ${esc(e.favorable_note)}</span>`:''}</div></div>
        <div><div class="cur-k">B73</div><div class="cur-v">${b73HTML(e)} <span class="muted">${esc(GT_LONG[s.b73]||'')}</span></div></div>
        <div><div class="cur-k">Priority</div><div class="cur-v">${prioPill(s.priority)} <span class="muted" data-tt="The composite AI score: the mean of the standardized PlantCAD1, PlantCAD2 and ESM1, ESM2 scores the site has, as a z against the release's missense sites; the tiers are its 5th, 25th and 80th percentiles.">composite ${s.combined==null?'—':(s.combined>0?'+':'')+(+s.combined).toFixed(2)+' z · '+(s.combinedN||0)+' of 4 scores'+(compositePct(s.combined)==null?'':' · '+ordinal(compositePct(s.combined))+' percentile')}</span></div></div>
      </div>
      <div class="cur-k" style="margin-top:14px">Scores${s.rank?` <span class="muted" style="text-transform:none;font-weight:400">· rank among the ${s.rankPool} missense variants of the gene that have a carrier (1 = most negative)</span>`:''}</div>
      <div class="cur-scores">${scores}</div>
      ${s.trait ? traitHTML(s.trait) : ''}
      <div class="cur-two">
        <div><div class="cur-k">Homozygous carriers by subpopulation</div>
          <table class="cur-mini"><tbody>${subs || '<tr><td class="muted">No homozygous carrier</td></tr>'}</tbody></table></div>
        <div><div class="cur-k">Carriers by country of origin</div>
          <table class="cur-mini"><tbody>${ctys}</tbody></table>
          ${s.country.length>12?`<button class="link-btn" onclick="this.previousElementSibling.querySelectorAll('.cur-more').forEach(r=>r.hidden=false);this.remove()">Show all ${s.country.length} countries</button>`:''}</div>
      </div>
      <p style="margin-top:14px">${esc(e.note||'')}</p>${pub}${review}
      <div class="cur-k" style="margin-top:12px">References</div><ul class="cur-refs">${refs}</ul></div>`;
  }
  function traitHTML(t){
    const head = `<div class="cur-k" style="margin-top:14px">${esc(t.name)} by genotype <span class="muted" style="text-transform:none;font-weight:400">· GRIN descriptor ${t.url?`<a href="${esc(t.url)}" target="_blank" rel="noopener">${esc(t.descriptor)}</a>`:esc(t.descriptor)}</span></div>`;
    if (t.scale === 'numeric'){
      const u = t.unit ? ` ${esc(t.unit)}` : '';
      return head + `<table class="cur-mini cur-trait"><tbody>
        <tr><td>Homozygous for the alternate allele</td><td class="num"><b>${fmt(t.alt.mean)}</b>${u} <span class="muted">(n = ${t.alt.n.toLocaleString()})</span></td></tr>
        <tr><td>Homozygous for the reference allele</td><td class="num"><b>${fmt(t.ref.mean)}</b>${u} <span class="muted">(n = ${t.ref.n.toLocaleString()})</span></td></tr></tbody></table>`;
    }
    return head + `<table class="cur-mini cur-trait"><thead><tr><th>${esc(t.name)}</th><th class="num">Homozygous alternate</th></tr></thead><tbody>${(t.codes||[]).map(c=>
      `<tr><td>${esc(c.label)} <span class="muted">(${esc(c.code)})</span></td><td class="num">${c.alt.toLocaleString()} of ${c.lines.toLocaleString()}${pct(c.alt,c.lines)}</td></tr>`).join('')}</tbody></table>`;
  }

  /* ---------- hand-offs ---------- */
  /* the site-wide set (S.dataset, shared with the other tools), else the first listed */
  function ds(){ const L=Data.datasets(); return (S.dataset && L.some(d=>d.id===S.dataset)) ? S.dataset : L[0].id; }
  function setShort(){ const d=Data.datasetById(ds()); return d ? (d.short || d.sub || d.name) : ''; }
  async function interval(e){
    const g = await Data.lookupGene(e.gene);
    if (!g || !g.chr || g.chr !== e.chr) return {chr:e.chr, start:+e.pos, end:+e.pos};
    return {chr:g.chr, start:Math.min(+g.start, +e.pos), end:Math.max(+g.end, +e.pos)};
  }

  function injectCSS(){
    if (document.getElementById('snpcurate-css')) return;
    const s=document.createElement('style'); s.id='snpcurate-css';
    s.textContent=`
      .cur-grid{display:flex;gap:22px;flex-wrap:wrap}
      .cur-k{font-size:10.5px;font-weight:600;color:var(--muted);text-transform:uppercase;letter-spacing:.4px;margin-bottom:4px}
      .cur-v{font-size:14px;color:var(--ink)}
      .cur-legend{display:flex;flex-direction:column;gap:6px;margin-bottom:6px;font-size:13px}
      .cur-lg{display:flex;align-items:baseline;gap:8px}
      .cur-filters .fld input{border:1px solid var(--line);border-radius:9px;padding:8px 10px;min-width:min(240px,100%)}
      .cur-sub{font-size:11.5px;color:var(--muted)}
      .cur-out{color:#9a5b00}
      .cur-ref{font-size:12px;white-space:nowrap}
      .cur-table td{vertical-align:top}
      .cur-record{margin-top:16px}
      .cur-rh{display:flex;justify-content:space-between;gap:10px;align-items:flex-start}
      .cur-sym{font-size:17px} .cur-lbl{font-size:15px;color:var(--ink)}
      .cur-actions{display:flex;gap:8px;flex-wrap:wrap;align-items:center;margin:12px 0 14px}
      .cur-facts{row-gap:12px}
      .cur-scores{display:flex;flex-wrap:wrap;gap:8px;margin-top:6px}
      .cur-score{display:flex;flex-direction:column;gap:1px;background:#f5f8fc;border:1px solid var(--line);border-radius:9px;padding:6px 10px;min-width:92px;font-size:11.5px;color:var(--muted)}
      .cur-score b{font-size:15px;color:var(--ink)}
      .cur-two{display:flex;gap:24px;flex-wrap:wrap;margin-top:14px}
      .cur-two>div{flex:1 1 260px;min-width:0}
      .cur-mini{border-collapse:collapse;font-size:12.5px;margin-top:6px;width:100%;max-width:420px}
      .cur-mini td,.cur-mini th{padding:3px 8px 3px 0;border-bottom:1px solid #eef1f5;text-align:left}
      .cur-mini td.num,.cur-mini th.num{text-align:right}
      .cur-trait{max-width:520px}
      .cur-why{background:#f2f4f7;border:1px solid #d5dae2;border-radius:9px;padding:9px 12px;margin:12px 0;font-size:13px}
      .cur-review{background:#fff7e6;border:1px solid #f0d9a8;border-left:4px solid #c27c0e;border-radius:9px;padding:9px 12px;margin:10px 0;font-size:13px}
      .cur-refs{margin:6px 0 0 18px;padding:0;font-size:12.5px;line-height:1.6}
      .cur-refs a{word-break:break-all}
      .cur-pub{font-size:13px;margin:6px 0 0}
      .cur-lines{margin:0 0 12px}
      .cur-lines-h{display:flex;justify-content:space-between;gap:10px;align-items:flex-start}
      .cur-lines-ctl{display:flex;gap:10px;flex-wrap:wrap;align-items:flex-start;margin-top:10px}
      .cur-lines-ctl textarea{flex:1 1 260px;min-width:min(260px,100%);border:1px solid var(--line);border-radius:9px;padding:8px 10px;font-family:var(--mono);font-size:12.5px}
      .cur-lines-btns{display:flex;gap:8px;flex-wrap:wrap;align-items:center}
      .cur-lines-acts{display:flex;gap:10px;flex-wrap:wrap;align-items:center;margin:12px 0 6px}
      .cur-lines-wrap{max-height:520px}
      .cur-lines-tbl{border-collapse:separate;border-spacing:0;font-size:12.5px}
      .cur-lines-tbl th,.cur-lines-tbl td{border-bottom:1px solid #eef1f5;padding:4px 6px;white-space:nowrap}
      .cur-lines-tbl thead th{position:sticky;top:0;background:#fff;z-index:1;vertical-align:bottom;text-align:left}
      .cur-lines-tbl th.cur-lrow{position:sticky;left:0;background:#fff;z-index:2;text-align:left;font-weight:500;min-width:160px}
      .cur-lines-tbl thead th.cur-lrow{z-index:3}
      .cur-lines-tbl th.cur-lcol{cursor:pointer;max-width:92px;white-space:normal;font-weight:500}
      .cur-lines-tbl th.cur-lcol:hover{background:#f5f8fc}
      .cur-lsym{display:block;font-weight:600} .cur-llab{display:block;font-size:11px;color:var(--muted);line-height:1.2}
      .cur-lc{text-align:center;font-family:var(--mono);font-weight:600;width:34px}
      .cur-lc-ref{color:#9aa3b2} .cur-lc-missing{color:#b0b7c3} .cur-lc-alt{background:#fde9cc} .cur-lc-het{background:#fff7e6}
      .cur-lc-favhom{background:#cfe8d6;color:#176c3a} .cur-lc-favhet{background:#e7f3ec;color:#176c3a}
      .cur-key{display:inline-block;width:auto;padding:0 6px;border-radius:5px;margin:0 2px}
      .cur-lines-tbl td.num{text-align:right}
      .cur-fav{display:inline-block;font-size:12px;font-weight:600;padding:2px 8px;border-radius:999px;border:1px solid var(--line);background:#f5f8fc;color:var(--ink)}
      .cur-fav-alt{background:#e7f3ec;border-color:#bfe0cb;color:#176c3a} .cur-fav-ref{background:#eaf1fc;border-color:#c5d6f3;color:#274b8f}
      .cur-fav-depends{background:#fff7e6;border-color:#f0d9a8;color:#8a5a0b} .cur-fav-unknown{color:var(--muted)}
      .cur-b73{font-family:var(--mono);font-size:12px;padding:2px 7px;border-radius:7px;border:1px solid var(--line);background:#f5f8fc}
      .cur-b73-alt{background:#fde9cc;border-color:#f0c58a} .cur-b73-het{background:#efe0fb;border-color:#d7bdf3}`;
    document.head.appendChild(s);
  }

  window.CURATE = {
    setDataset(id){ if (!Data.datasets().some(d=>d.id===id)) return; S.dataset=id; render(); },
    /* the lines panel */
    loadLines(text){ const r=resolveLines(text); setLines(r.ids, r); },
    useSelection(){ setLines([...(S.selected||[])]); },
    useFounders(){ setLines(Data.accessionsFor(ds()).filter(a=>a.namFounder).map(a=>a.id)); },
    clearLines(){ CU.lines=[]; CU.linesReport=null; const host=document.getElementById('curLines'); if (host) host.innerHTML=linesPanelHTML(); writeRoute(); },
    linesTSV, linesState(){ return {ids:CU.lines.slice(), report:CU.linesReport}; },
    linesDownload(){
      const blob=new Blob([linesTSV()],{type:'text/tab-separated-values'}), u=URL.createObjectURL(blob), a=document.createElement('a');
      a.href=u; a.download=`snpcurate_lines_${CU.lines.length}x${siteEntries().length}.tsv`; document.body.appendChild(a); a.click(); a.remove();
      setTimeout(()=>URL.revokeObjectURL(u), 1000);
    },
    linesToSelection(){
      if (!CU.lines.length) return;
      const before=[...(S.selected||[])];
      S.selected=new Set(CU.lines); if (typeof refreshSelChip==='function') refreshSelChip(true);
      if (typeof toast==='function') toast(`Selection is now <b>${CU.lines.length.toLocaleString()}</b> line${CU.lines.length===1?'':'s'}. SNPVersity uses it for its next query.`,
        [{label:'Undo', run:()=>{ S.selected=new Set(before); if (typeof refreshSelChip==='function') refreshSelChip(true); }}, {label:'Open SNPVersity', run:()=>go('snpversity')}]);
    },
    /* a column of the lines panel: the site's carriers (homozygous and heterozygous) become the selection */
    selectCarriers(id){
      const e=byId(id); if (!e || !e.site) return;
      const ids=e.site.carriers.hom.concat(e.site.carriers.het), before=[...(S.selected||[])];
      S.selected=new Set(ids); if (typeof refreshSelChip==='function') refreshSelChip(true);
      if (typeof toast==='function') toast(`Selection is now the <b>${ids.length.toLocaleString()}</b> carriers of ${esc(e.symbol)} ${esc(e.label)}.`,
        [{label:'Undo', run:()=>{ S.selected=new Set(before); if (typeof refreshSelChip==='function') refreshSelChip(true); }}, {label:'Open SNPVersity', run:()=>go('snpversity')}]);
    },
    setFilter(k, v){ CU[k]=v; const t=document.getElementById('curTable'); if (t){ t.innerHTML=tableHTML(); if (typeof attachTT==='function') attachTT(); } },
    sort(k){ if (CU.sortKey===k) CU.sortDir*=-1; else { CU.sortKey=k; CU.sortDir = k==='carriers' ? -1 : 1; }
      const t=document.getElementById('curTable'); if (t){ t.innerHTML=tableHTML(); if (typeof attachTT==='function') attachTT(); } },
    open(id){ S.curateId = (S.curateId===id ? null : id); render(); },
    close(){ S.curateId = null; render(); },
    async toVersity(id){
      const e = byId(id); if (!e || !e.site) return;
      const iv = await interval(e);
      Handoff.toVersity({from:'SNPCurate', dataset:ds(), gene:e.gene, chr:iv.chr, start:iv.start, end:iv.end,
        accessions:e.site.carriers.hom.concat(e.site.carriers.het), merge:'replace',
        note:`carriers of ${e.symbol} ${e.label} (${e.id})`});
    },
    toFunction(id){ const e=byId(id); if (!e) return; S.functionGene=e.gene; S.functionDataset=ds(); go('snpfunction'); },
    async toMap(id){
      const e = byId(id); if (!e || !e.site) return;
      CU.busy = id; const b=document.getElementById('curBusy'); if (b) b.textContent='Querying all lines…';
      try {
        const res = await Data.queryVariants(ds(), e.chr, +e.pos, +e.pos, Data.accessionsFor(ds()).map(a=>a.id));
        res.q = {dataset:ds(), chr:e.chr, lo:+e.pos, hi:+e.pos};
        S.geoInput = resultHandoff(res);
        go('snpgeo');
      } finally { CU.busy = null; }
    },
    entries, byId,
  };

  SNPTools.register('snpcurate', { render });
})();
